#!/usr/bin/env bash
#
# verify.sh — verify the T263 German OCR reference suite (issue #263).
#
# Fails closed. It proves, without trusting the generator's own word:
#   1. the generator's `--check` reports every generated byte as current;
#   2. the reference PDF SHA-256 and size equal the values pinned in the
#      ground truth and in the dev catalogue, and the existing fixture pins
#      (`sf-001`, `sf-004`) are untouched;
#   3. the embedded font's own `cmap` covers every required character
#      (Ä Ö Ü ä ö ü ß ẞ € ² ³) and the tracked font SHA-256 still matches;
#   4. the ground truth is structurally complete: every critical line has a
#      positive display-space rectangle inside its page, every required
#      character and authority term appears, and every field references an
#      existing label line;
#   5. when Poppler is available, the PDF text layer contains exactly the
#      printed code points of every page after whitespace removal (control
#      path, never OCR evidence).
#
# Usage:
#   bash tools/corpus/de-ocr/verify.sh
#   bash tools/corpus/de-ocr/verify.sh --json
#
# Exit codes: 0 verified, 1 verification failure, 2 usage error.
set -euo pipefail

SCRIPT_DIR="$(CDPATH= cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(CDPATH= cd -- "$SCRIPT_DIR/../../.." && pwd)"

if ! command -v python3 >/dev/null 2>&1; then
  echo "verify.sh: python3 is required but was not found" >&2
  exit 2
fi

DART="${DART:-$(command -v dart || true)}"
if [ -z "$DART" ] && [ -x "$HOME/flutter/bin/dart" ]; then
  DART="$HOME/flutter/bin/dart"
fi

cd "$ROOT_DIR" || exit 2
if [ -n "$DART" ]; then
  "$DART" run tools/corpus/synthetic/generate.dart --check >/dev/null
else
  echo "verify.sh: dart SDK not found; the byte check is NOT_RUN" >&2
  exit 1
fi

exec python3 - "$@" <<'PY'
"""Verify the T263 German OCR reference suite."""
import json
import pathlib
import shutil
import struct
import subprocess
import sys

ROOT = pathlib.Path.cwd()
GROUND_TRUTH = ROOT / "tools/corpus/de-ocr/reference-de.ground-truth.json"
CATALOG = ROOT / "apps/feldexa_app/assets/fixtures/catalog.json"
FIXTURE = "sf-005"
FONT = ROOT / "apps/feldexa_app/assets/fonts/NotoSans-Regular.ttf"
FONT_SHA256 = "97eaf07030b89da4eceace86b12f4d7debb3cb212082c3938803eac7111221c9"
PINS = {
    "sf-001": "22c939ccc788f24868a115e5f635d1c0e0618d760b28518a4bd5e039f8caa038",
    "sf-004": "009c3babd2013e13fad9ef5977ec3d4c1d5842a52da0718e4ac06e3ff39d171e",
}
REQUIRED_CHARACTERS = list("ÄÖÜäöüßẞ€²³")
REQUIRED_TERMS = [
    "Straße",
    "Größe",
    "Gebühr",
    "Geschäftszeichen",
    "Staatsangehörigkeit",
    "Überweisung",
    "Erklärung",
    "Anträge",
]
WHITESPACE = set(" \t\n\r\u00a0\u202f\u2009")

failures = []


def fail(message):
    failures.append(message)


def sha256(path):
    digest = subprocess.run(
        ["sha256sum", str(path)], capture_output=True, check=True, text=True
    ).stdout.split()[0]
    return digest


def cmap_code_points(path):
    data = path.read_bytes()
    num_tables = struct.unpack(">H", data[4:6])[0]
    tables = {}
    for index in range(num_tables):
        record = 12 + index * 16
        tag = data[record : record + 4].decode("latin-1")
        offset, length = struct.unpack(">II", data[record + 8 : record + 16])
        tables[tag] = (offset, length)
    base, _ = tables["cmap"]
    subtable_count = struct.unpack(">H", data[base + 2 : base + 4])[0]
    coverage = set()
    for index in range(subtable_count):
        record = base + 4 + index * 8
        platform, encoding, offset = struct.unpack(">HHI", data[record : record + 8])
        offset += base
        fmt = struct.unpack(">H", data[offset : offset + 2])[0]
        if not ((platform == 3 and encoding == 1) or (platform == 0 and encoding == 3)):
            continue
        if fmt != 4:
            continue
        seg_x2 = struct.unpack(">H", data[offset + 6 : offset + 8])[0]
        segments = seg_x2 // 2
        ends = offset + 14
        starts = ends + seg_x2 + 2
        for segment in range(segments):
            end = struct.unpack(">H", data[ends + 2 * segment : ends + 2 * segment + 2])[0]
            start = struct.unpack(">H", data[starts + 2 * segment : starts + 2 * segment + 2])[0]
            if start <= end and start != 0xFFFF:
                coverage.update(range(start, end + 1))
    return coverage


def page_code_points(text):
    return sorted(
        [character for character in text if character not in WHITESPACE]
    )


def main(json_output):
    ground_truth = json.loads(GROUND_TRUTH.read_text(encoding="utf-8"))
    catalog = json.loads(CATALOG.read_text(encoding="utf-8"))
    entry = next((item for item in catalog["fixtures"] if item["id"] == FIXTURE), None)
    if entry is None:
        fail(f"catalogue has no {FIXTURE} entry")
        return report(json_output)
    pdf = ROOT / entry["assetPath"]
    if not pdf.is_file():
        fail(f"missing fixture {entry['assetPath']}")
        return report(json_output)

    digest = sha256(pdf)
    if digest != ground_truth["pdf"]["sha256"]:
        fail("fixture sha256 differs from the ground truth")
    if digest != entry["sha256"]:
        fail("fixture sha256 differs from the catalogue pin")
    if pdf.stat().st_size != ground_truth["pdf"]["sizeBytes"]:
        fail("fixture size differs from the ground truth")

    for fixture_id, pinned in PINS.items():
        item = next((x for x in catalog["fixtures"] if x["id"] == fixture_id), None)
        if item is None or item["sha256"] != pinned:
            fail(f"existing pin for {fixture_id} changed")

    if sha256(FONT) != FONT_SHA256:
        fail("bundled font sha256 changed")
    coverage = cmap_code_points(FONT)
    for character in REQUIRED_CHARACTERS:
        if ord(character) not in coverage:
            fail(f"embedded font does not cover U+{ord(character):04X}")

    lines = ground_truth["lines"]
    pages = ground_truth["pages"]
    page_sizes = {page["index"]: page for page in pages}
    critical = 0
    printed = {}
    for line in lines:
        critical += 1 if line["critical"] else 0
        rect = line["rect"]
        page = page_sizes[line["pageIndex"]]
        if not (
            rect["widthPt"] > 0
            and rect["heightPt"] > 0
            and rect["xPt"] >= 0
            and rect["yPt"] >= 0
            and rect["xPt"] + rect["widthPt"] <= page["widthPt"] + 1e-6
            and rect["yPt"] + rect["heightPt"] <= page["heightPt"] + 1e-6
        ):
            fail(f"line {line['id']} rectangle is outside its page")
        if line["textNfd"] == line["text"] and any(c in "ÄÖÜäöü" for c in line["text"]):
            fail(f"line {line['id']} has no NFD spelling")
        printed[line["pageIndex"]] = printed.get(line["pageIndex"], "") + line["text"]
    if critical == 0:
        fail("no critical lines are declared")

    all_text = "".join(printed.values())
    for character in REQUIRED_CHARACTERS:
        if character not in all_text:
            fail(f"required character {character} is not printed")
    for term in REQUIRED_TERMS:
        if term not in all_text:
            fail(f"required authority term {term} is not printed")

    line_ids = {line["id"] for line in lines}
    for field in ground_truth["fields"]:
        if field["labelLineId"] not in line_ids:
            fail(f"field {field['id']} references a missing label line")
        if field["label"] not in all_text:
            fail(f"field {field['id']} label is not printed")

    pdftotext = shutil.which("pdftotext")
    text_layer = "NOT_RUN"
    if pdftotext:
        result = subprocess.run(
            [pdftotext, "-enc", "UTF-8", str(pdf), "-"],
            capture_output=True,
            check=True,
        )
        extracted = result.stdout.decode("utf-8")
        extracted_pages = [page for page in extracted.split("\f") if page.strip()]
        if len(extracted_pages) != len(printed):
            fail("text layer page count differs from the ground truth")
        for index, page_text in enumerate(extracted_pages):
            if page_code_points(page_text) != page_code_points(printed[index]):
                fail(f"text layer code points differ on page {index}")
        text_layer = "PASS" if not failures else "FAIL"

    return report(json_output, text_layer=text_layer, digest=digest)


def report(json_output, text_layer="NOT_RUN", digest=""):
    payload = {
        "suiteId": "de-ocr-1.0.0",
        "fixture": FIXTURE,
        "fixtureSha256": digest,
        "textLayer": text_layer,
        "result": "PASS" if not failures else "FAIL",
        "failures": failures,
    }
    if json_output:
        print(json.dumps(payload, indent=2))
    else:
        print(f"T263 suite {payload['suiteId']} ({FIXTURE}): {payload['result']}")
        print(f"fixture sha256 {digest or 'unknown'}")
        print(f"text layer {text_layer}")
        for failure in failures:
            print(f"FAIL {failure}")
        if not failures:
            print(
                "OK fixture pin, font coverage, ground-truth structure, and "
                "text-layer code points verified"
            )
    return 0 if not failures else 1


if __name__ == "__main__":
    sys.exit(main("--json" in sys.argv[1:]))
PY
